P=dict(ch=3,nv=43,V=V,per=[14,15,14],out='/home/claude/work/gita/Gita_Chapter03.html',
 title='The Path of Action · Bhagavad Gītā Chapter 3 · srini.presents',
 desc='Bhagavad Gītā chapter 3, Karma Yoga, every śloka explained: why no one can avoid action, work done as yajña, the wheel of give and take, leaders who set the example, the ego that claims to be the doer, svadharma, and desire as the enemy. All 43 ślokas in IAST, each on two pages.',
 burst='CHAPTER 3 OF 18',h1='THE PATH OF ACTION',series='BHAGAVAD GĪTĀ · CHAPTER 3 · KARMA YOGA',tag='Work as offering · every śloka explained',cover=cover,
 where=[f'In {chl(2)} Kṛṣṇa taught that the Self never dies, and that one should act without craving the fruit, with an even mind.',
  'Arjuna is confused: if understanding is higher, why fight? Chapter 3 answers: no one can stop acting, so act well. Do your work as an offering (yajña), for the good of the world, without the ego claiming it. And know your real enemy: desire.'],
 wtalk=("Can't I just quit and meditate?","Kṛṣṇa says no one can stop acting for even a moment. The real question is how you act, not whether."),
 fullnote=FULLNOTE,
 secs=[('THE QUESTION',1),('NO ESCAPE FROM ACTION',4),('YAJÑA',9),('FOR THE WORLD',17),('THE EGO AND OFFERING',27),('THE ENEMY',36)],
 end=['<b>The question (3.1–3).</b> Knowledge or action? Kṛṣṇa: two paths for two natures.',
  '<b>No escape (3.4–8).</b> No one can stop acting; a pretend renouncer is a hypocrite. Do your due work.',
  '<b>Yajña (3.9–16).</b> Work done as an offering frees; the world runs on give and take.',
  '<b>For the world (3.17–35).</b> Janaka and the Lord himself work for loka-saṅgraha; the ego is not the doer; offer all action; follow your own dharma.',
  '<b>The enemy (3.36–43).</b> Desire, turning into anger, covers wisdom; know the Self and slay it.'],
 endsub='Chapter 3 in five lines',
 next=("What's next?",f'{chl(4)}: Knowledge and action. Kṛṣṇa reveals that he taught this yoga long ago, explains why he takes birth age after age, and shows how knowledge burns all karma to ash.'),
 endkey='<b>act, as an offering, for the world</b>.',
 foot=FOOT(3))
build2(P)
